function voyalo_upload(string $key): ?string {
    if(empty($_FILES[$key])||$_FILES[$key]['error']===UPLOAD_ERR_NO_FILE)return null;
    if($_FILES[$key]['error']!==UPLOAD_ERR_OK||$_FILES[$key]['size']>4*1024*1024)throw new RuntimeException('Image invalide ou supérieure à 4 Mo.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$key]['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if(!isset($extensions[$mime]))throw new RuntimeException('Formats acceptés : JPG, PNG ou WebP.');
    $name=bin2hex(random_bytes(16)).'.'.$extensions[$mime];$directory=__DIR__.'/../uploads';
    if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))throw new RuntimeException('Le dossier de téléversement est indisponible.');
    if(!move_uploaded_file($_FILES[$key]['tmp_name'],$directory.'/'.$name))throw new RuntimeException('Impossible d’enregistrer cette image.');
    return '/uploads/'.$name;
}
function valid_date(string $date): bool { $d=DateTime::createFromFormat('Y-m-d',$date);return $d&&$d->format('Y-m-d')===$date; }
function future_date(string $date): bool { return valid_date($date)&&$date>=date('Y-m-d'); }
function valid_time(string $time): bool { return preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time)===1; }
function post_text(string $key,int $max,bool $required=false): string { $value=trim((string)($_POST[$key]??''));$length=function_exists('mb_strlen')?mb_strlen($value,'UTF-8'):strlen($value);if(($required&&$value==='')||$length>$max)throw new RuntimeException('Vérifiez le contenu des champs obligatoires et leurs longueurs.');return $value; }

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$command=$_POST['command']??'create';
    try{
        if($command==='update'){
            $id=(int)($_POST['id']??0);
            if($kind==='hotels'){$image=voyalo_upload('image');$q=$pdo->prepare('UPDATE hotels SET nom=?,ville=?,adresse=?,description=?,etoiles=?,image_principale=COALESCE(?,image_principale) WHERE id=?');$q->execute([post_text('nom',180,true),post_text('ville',120,true),post_text('adresse',255,true),post_text('description',10000),max(1,min(5,(int)($_POST['etoiles']??3))),$image,$id]);}
            elseif($kind==='rooms'){$capacity=max(1,(int)($_POST['capacite']??1));$q=$pdo->prepare("SELECT COALESCE(MAX(nb_personnes),0) FROM room_bookings WHERE room_id=? AND statut IN ('en_attente','confirmee','payee') AND date_depart>=CURDATE()");$q->execute([$id]);if($capacity<(int)$q->fetchColumn())throw new RuntimeException('La capacité ne peut pas être inférieure au nombre de voyageurs des séjours réservés.');$image=voyalo_upload('image');$q=$pdo->prepare('UPDATE rooms SET type=?,capacite=?,prix_nuit=?,image=COALESCE(?,image) WHERE id=?');$q->execute([post_text('type',100,true),$capacity,max(0,(int)($_POST['prix_nuit']??0)),$image,$id]);}
            elseif($kind==='routes'){$newCapacity=max(1,(int)($_POST['places_totales']??1));$q=$pdo->prepare('SELECT COALESCE(MAX(vendues),0) FROM (SELECT COALESCE(SUM(b.nb_billets),0) vendues FROM trips_schedule s LEFT JOIN ticket_bookings b ON b.schedule_id=s.id WHERE s.route_id=? GROUP BY s.id) sold');$q->execute([$id]);if($newCapacity<(int)$q->fetchColumn())throw new RuntimeException('La capacité ne peut pas être inférieure aux billets déjà vendus.');$transport=$_POST['type_transport']??'bus';if(!in_array($transport,['bus','avion'],true))throw new RuntimeException('Type de transport invalide.');$q=$pdo->prepare('UPDATE routes SET origine=?,destination=?,type_transport=?,compagnie=?,prix=?,places_totales=? WHERE id=?');$q->execute([post_text('origine',120,true),post_text('destination',120,true),$transport,post_text('compagnie',160,true),max(0,(int)($_POST['prix']??0)),$newCapacity,$id]);}
            elseif($kind==='schedules'){$date=$_POST['date_depart']??'';$time=$_POST['heure_depart']??'';if(!future_date($date)||!valid_time($time))throw new RuntimeException('Date ou heure de départ invalide.');$q=$pdo->prepare('UPDATE trips_schedule SET date_depart=?,heure_depart=? WHERE id=?');$q->execute([$date,$time.':00',$id]);}
            elseif($kind==='packages'){$image=voyalo_upload('image');$q=$pdo->prepare('UPDATE packages SET titre=?,description=?,duree_jours=?,prix=?,itineraire=?,image_principale=COALESCE(?,image_principale) WHERE id=?');$q->execute([post_text('titre',180,true),post_text('description',10000),max(1,(int)($_POST['duree_jours']??1)),max(0,(int)($_POST['prix']??0)),post_text('itineraire',10000),$image,$id]);}
            elseif($kind==='departures'){$date=$_POST['date_depart']??'';if(!future_date($date))throw new RuntimeException('Date de départ invalide.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT (SELECT COALESCE(SUM(b.nb_participants),0) FROM package_bookings b WHERE b.departure_id=d.id) vendues FROM package_departures d WHERE d.id=? FOR UPDATE');$q->execute([$id]);$sold=$q->fetch();if(!$sold)throw new RuntimeException('Départ introuvable.');$total=max(0,(int)($_POST['places']??0));if($total<(int)$sold['vendues'])throw new RuntimeException('La capacité ne peut pas être inférieure aux places déjà réservées.');$q=$pdo->prepare('UPDATE package_departures SET date_depart=?,places=? WHERE id=?');$q->execute([$date,$total-(int)$sold['vendues'],$id]);$pdo->commit();}
            elseif($kind==='promotions'){$q=$pdo->prepare('UPDATE promotions SET code=?,reduction_pct=?,date_debut=?,date_fin=? WHERE id=?');$q->execute([strtoupper(post_text('code',40,true)),min(100,max(0,(float)($_POST['reduction_pct']??0))),($_POST['date_debut']??'')?:null,($_POST['date_fin']??'')?:null,$id]);}
            else throw new RuntimeException('Modification non disponible pour ce type de fiche.');$msg='Modifications enregistrées.';
        }elseif($command==='toggle'){
            $id=(int)($_POST['id']??0);
            $targets=['hotels'=>['hotels','actif'],'rooms'=>['rooms','disponible'],'routes'=>['routes','actif'],'packages'=>['packages','actif'],'promotions'=>['promotions','actif']];
            if(!isset($targets[$kind]))throw new RuntimeException('Action non permise.');[$table,$column]=$targets[$kind];$q=$pdo->prepare("UPDATE $table SET $column=IF($column=1,0,1) WHERE id=?");$q->execute([$id]);$msg='Disponibilité mise à jour.';
        }elseif($command==='role'&&$kind==='users'){
            $id=(int)($_POST['id']??0);$role=$_POST['role']??'';if(!in_array($role,['client','agent','admin'],true))throw new RuntimeException('Rôle invalide.');if($id===(int)user()['id']&&$role!=='admin')throw new RuntimeException('Vous ne pouvez pas retirer votre propre accès administrateur.');$q=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$q->execute([$role,$id]);$msg='Rôle utilisateur mis à jour.';
        }elseif($command==='seats'&&$kind==='schedules'){
            $id=(int)($_POST['id']??0);$pdo->beginTransaction();$q=$pdo->prepare('SELECT r.places_totales,(SELECT COALESCE(SUM(b.nb_billets),0) FROM ticket_bookings b WHERE b.schedule_id=s.id) vendues FROM trips_schedule s JOIN routes r ON r.id=s.route_id WHERE s.id=? FOR UPDATE');$q->execute([$id]);$capacity=$q->fetch();if(!$capacity)throw new RuntimeException('Départ introuvable.');$max=max(0,(int)$capacity['places_totales']-(int)$capacity['vendues']);$seats=min($max,max(0,(int)($_POST['places_restantes']??0)));$q=$pdo->prepare('UPDATE trips_schedule SET places_restantes=? WHERE id=?');$q->execute([$seats,$id]);$pdo->commit();$msg='Places restantes mises à jour sans dépasser les billets déjà vendus.';
        }elseif($command==='departure_seats'&&$kind==='departures'){
            $id=(int)($_POST['id']??0);$pdo->beginTransaction();$q=$pdo->prepare('SELECT (SELECT COALESCE(SUM(b.nb_participants),0) FROM package_bookings b WHERE b.departure_id=d.id) vendues FROM package_departures d WHERE d.id=? FOR UPDATE');$q->execute([$id]);$sold=$q->fetch();if(!$sold)throw new RuntimeException('Départ introuvable.');$capacity=max(0,(int)($_POST['places']??0));$q=$pdo->prepare('UPDATE package_departures SET places=? WHERE id=?');$q->execute([max(0,$capacity-(int)$sold['vendues']),$id]);$pdo->commit();$msg='Places disponibles mises à jour.';
        }elseif($kind==='hotels'){
            $image=voyalo_upload('image');$equip=array_values(array_filter(array_map('trim',explode(',',post_text('equipements',1000)))));$json=json_encode($equip,JSON_UNESCAPED_UNICODE);$stars=max(1,min(5,(int)($_POST['etoiles']??3)));
            $q=$pdo->prepare('INSERT INTO hotels(nom,ville,adresse,description,etoiles,image_principale,equipements) VALUES(?,?,?,?,?,?,?)');$q->execute([post_text('nom',180,true),post_text('ville',120,true),post_text('adresse',255,true),post_text('description',10000),$stars,$image,$json]);$msg='Hébergement ajouté. Ajoutez ses chambres depuis l’onglet Chambres.';
        }elseif($kind==='rooms'){
            $hotel=(int)($_POST['hotel_id']??0);$image=voyalo_upload('image');$q=$pdo->prepare('INSERT INTO rooms(hotel_id,type,capacite,prix_nuit,disponible,image) SELECT id,?,?,?,?,? FROM hotels WHERE id=? AND actif=1');$q->execute([post_text('type',100,true),max(1,(int)($_POST['capacite']??1)),max(0,(int)($_POST['prix_nuit']??0)),(int)($_POST['disponible']??1),$image,$hotel]);if(!$q->rowCount())throw new RuntimeException('Sélectionnez un hôtel actif.');$msg='Chambre ajoutée.';
        }elseif($kind==='routes'){
            $transport=$_POST['type_transport']??'bus';if(!in_array($transport,['bus','avion'],true))throw new RuntimeException('Type de transport invalide.');$pdo->beginTransaction();$places=max(1,(int)($_POST['places_totales']??1));$q=$pdo->prepare('INSERT INTO routes(origine,destination,type_transport,compagnie,prix,places_totales) VALUES(?,?,?,?,?,?)');$q->execute([post_text('origine',120,true),post_text('destination',120,true),$transport,post_text('compagnie',160,true),max(0,(int)($_POST['prix']??0)),$places]);$route=(int)$pdo->lastInsertId();$date=$_POST['date_depart']??'';$time=$_POST['heure_depart']??'';if($date!==''||$time!==''){if(!future_date($date)||!valid_time($time))throw new RuntimeException('Date ou heure de départ invalide.');$q=$pdo->prepare('INSERT INTO trips_schedule(route_id,date_depart,heure_depart,places_restantes) VALUES(?,?,?,?)');$q->execute([$route,$date,$time.':00',$places]);}$pdo->commit();$msg='Trajet ajouté'.($date&&$time?' et départ programmé.':'.');
        }elseif($kind==='schedules'){
            $route=(int)($_POST['route_id']??0);$date=$_POST['date_depart']??'';$time=$_POST['heure_depart']??'';if(!future_date($date)||!valid_time($time))throw new RuntimeException('Date ou heure de départ invalide.');$q=$pdo->prepare('INSERT INTO trips_schedule(route_id,date_depart,heure_depart,places_restantes) SELECT id,?,?,places_totales FROM routes WHERE id=? AND actif=1');$q->execute([$date,$time.':00',$route]);if(!$q->rowCount())throw new RuntimeException('Sélectionnez un trajet actif.');$msg='Départ ajouté.';
        }elseif($kind==='packages'){
            $pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO packages(titre,description,duree_jours,prix,itineraire,image_principale) VALUES(?,?,?,?,?,?)');$q->execute([post_text('titre',180,true),post_text('description',10000),max(1,(int)($_POST['duree_jours']??1)),max(0,(int)($_POST['prix']??0)),post_text('itineraire',10000),voyalo_upload('image')]);$package=(int)$pdo->lastInsertId();$date=$_POST['date_depart']??'';if($date!==''){if(!future_date($date))throw new RuntimeException('Date de départ invalide.');$q=$pdo->prepare('INSERT INTO package_departures(package_id,date_depart,places) VALUES(?,?,?)');$q->execute([$package,$date,max(1,(int)($_POST['places']??20))]);}$pdo->commit();$msg='Circuit ajouté'.($date?' avec son premier départ.':'.');
        }elseif($kind==='departures'){
            $package=(int)($_POST['package_id']??0);$date=$_POST['date_depart']??'';if(!future_date($date))throw new RuntimeException('Date de départ invalide.');$q=$pdo->prepare('INSERT INTO package_departures(package_id,date_depart,places) SELECT id,?,? FROM packages WHERE id=? AND actif=1');$q->execute([$date,max(1,(int)($_POST['places']??20)),$package]);if(!$q->rowCount())throw new RuntimeException('Sélectionnez un circuit actif.');$msg='Départ de circuit ajouté.';
        }elseif($kind==='promotions'){
            $q=$pdo->prepare('INSERT INTO promotions(code,reduction_pct,date_debut,date_fin) VALUES(?,?,?,?)');$q->execute([strtoupper(post_text('code',40,true)),min(100,max(0,(float)($_POST['reduction_pct']??0))),($_POST['date_debut']??'')?:null,($_POST['date_fin']??'')?:null]);$msg='Code promotionnel ajouté.';
        }elseif($kind==='users'){
            $name=post_text('nom',120,true);$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';if(!$email||strlen($password)<12)throw new RuntimeException('Renseignez un email valide et un mot de passe de 12 caractères minimum.');$q=$pdo->prepare("INSERT INTO users(nom,email,password,telephone,role) VALUES(?,?,?,?, 'agent')");$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),post_text('telephone',30)]);$msg='Compte agent créé.';
        }
