}

$hotels=$pdo->query('SELECT id,nom,ville FROM hotels WHERE actif=1 ORDER BY ville,nom')->fetchAll();$routes=$pdo->query('SELECT id,origine,destination,compagnie,places_totales FROM routes WHERE actif=1 ORDER BY origine,destination')->fetchAll();$packages=$pdo->query('SELECT id,titre FROM packages WHERE actif=1 ORDER BY titre')->fetchAll();
