 'routes'=>'SELECT id,origine,destination,type_transport,compagnie,prix,places_totales,actif FROM routes ORDER BY id DESC LIMIT 100',
 'schedules'=>'SELECT s.id,CONCAT(r.origine,\' → \',r.destination) trajet,r.compagnie,s.date_depart,s.heure_depart,s.places_restantes,r.places_totales FROM trips_schedule s JOIN routes r ON r.id=s.route_id ORDER BY s.date_depart DESC,s.heure_depart DESC LIMIT 100',
 'packages'=>'SELECT id,titre,duree_jours,prix,actif FROM packages ORDER BY id DESC LIMIT 100',
 'departures'=>'SELECT d.id,p.titre circuit,d.date_depart,d.places places_restantes,d.places+(SELECT COALESCE(SUM(b.nb_participants),0) FROM package_bookings b WHERE b.departure_id=d.id) capacite_totale FROM package_departures d JOIN packages p ON p.id=d.package_id ORDER BY d.date_depart DESC LIMIT 100',
 'promotions'=>'SELECT id,code,reduction_pct,date_debut,date_fin,actif FROM promotions ORDER BY id DESC LIMIT 100',
